    root.set("data3D", libe57.VectorNode(imf, True))
    root.set("images2D", libe57.VectorNode(imf, True))
    return imf

def write_scan(imf, n, vals, with_int=True):
    scan_node = libe57.StructureNode(imf)
    scan_node.set("guid", libe57.StringNode(imf, "{s}"))
    proto = libe57.StructureNode(imf)
    def F(): return libe57.FloatNode(imf, 1.0, libe57.E57_DOUBLE, -1e30, 1e30)
    for nm in ("cartesianX","cartesianY","cartesianZ"): proto.set(nm, F())
    if with_int: proto.set("intensity", F())
    codecs = libe57.VectorNode(imf, True)
    points = libe57.CompressedVectorNode(imf, proto, codecs)
    scan_node.set("points", points)
